// @generated by the slice schematic 1.2.0 from its spec. Edit in place; reshape via the spec and --force.
import { Injectable, computed, inject, signal } from '@angular/core';
import type { BadgeVariants } from '@spartan-ng/helm/badge';
import { LoanService } from '../loan/loan.service';
import { BookService } from '../book/book.service';
import type { LoanFormModel } from '../loan/loan.schema';

type BadgeVariant = NonNullable<BadgeVariants['variant']>;

/** Every piece of spec text the screen shows. The template binds to these and never repeats them. */
const LOANS_TEXT = {
  title: 'Loans',
  plural: 'loans',
  createLabel: 'New loan',
  createTitle: 'Create loan',
  createDescription: 'Add a new loan.',
  editTitle: 'Edit loan',
  editDescription: "Change this loan's details and save.",
  deleteTitle: 'Delete loan?',
  deleteDescription: 'This loan will be permanently removed. This cannot be undone.',
  searchLabel: 'Search loans',
  searchPlaceholder: 'Search loans...',
  empty: 'No loans match this filter.',
  edit: 'Edit',
  delete: 'Delete',
  actions: 'Actions',
  filters: {
    extended: 'Extended only',
  },
  columns: {
    reference: 'Reference',
    branch: 'Branch',
    status: 'Status',
    extended: 'Extended loan',
    borrowedOn: 'Borrowed On',
  },
} as const;

const STATUS_VARIANTS: Readonly<Record<string, BadgeVariant>> = {
  Returned: 'default',
  Overdue: 'destructive',
};

@Injectable()
export class LoansViewModel {
  private readonly loanService = inject(LoanService);
  private readonly bookService = inject(BookService);

  readonly text = LOANS_TEXT;
  readonly loans = this.loanService.loans;

  readonly searchQuery = signal('');
  readonly extendedFilterOn = signal(false);

  /** The id of the loan being edited, '' for a new one, or null when closed. */
  readonly editing = signal<string | null>(null);

  readonly filtered = computed(() => {
    const q = this.searchQuery().toLowerCase();
    const extendedOn = this.extendedFilterOn();
    const rows = this.loans()
      .filter((item) => !extendedOn || item.extended)
      .filter(
        (item) =>
          !q || item.reference.toLowerCase().includes(q) || item.branch.toLowerCase().includes(q),
      );
    return rows;
  });

  readonly bookIdOptions = computed(() =>
    this.bookService.books().map((item) => ({ value: item.id, label: item.title })),
  );

  readonly editingLoan = computed(() => {
    const id = this.editing();
    return id ? this.loanService.byId(id) : undefined;
  });

  readonly statusVariant = (value: string): BadgeVariant => STATUS_VARIANTS[value] ?? 'secondary';

  toggleExtendedFilter(): void {
    this.extendedFilterOn.update((on) => !on);
  }

  startCreate(): void {
    this.editing.set('');
  }

  startEdit(id: string): void {
    this.editing.set(id);
  }

  cancel(): void {
    this.editing.set(null);
  }

  save(model: LoanFormModel): void {
    const id = this.editing();
    if (id) {
      this.loanService.update(id, model);
    } else {
      this.loanService.create(model);
    }
    this.editing.set(null);
  }

  remove(id: string): void {
    this.loanService.remove(id);
    if (this.editing() === id) this.editing.set(null);
  }
}
